function modal(title,body,onSave,saveLabel='Save'){const w=document.createElement('div');w.className='modal-backdrop';w.innerHTML=`<div class="modal"><div class="modal-head"><h3>${esc(title)}</h3><button class="icon-btn" data-close>×</button></div><div class="modal-body">${body}</div><div class="modal-actions"><button class="btn" data-close>Cancel</button><button class="btn primary" data-save>${esc(saveLabel)}</button></div></div>`;document.body.appendChild(w);qsa('[data-close]',w).forEach(b=>b.onclick=()=>w.remove());qs('[data-save]',w).onclick=()=>{const ok=onSave?.(w);if(ok!==false)w.remove()};return w}
